<script setup lang="ts">
import {onMounted,onUnmounted,ref,computed,defineAsyncComponent} from 'vue'
import {ArrowUpRight,ArrowRight,Layers3,Wallet,LayoutDashboard,ShieldCheck,LogOut,Menu,X,ReceiptText,KeyRound,UserRound,Gift,Sparkles,Bell,Settings2,Users,ChartNoAxesCombined,Activity,Server,Ticket,Package,BookOpen,ScrollText,Check} from 'lucide-vue-next'
import {api,action,toast,cash,notify,type Row} from './lib'
import Customer from './Customer.vue'
import ApiDocs from './components/ApiDocs.vue'
const Admin=defineAsyncComponent(()=>import('./Admin.vue'))
const user=ref<Row|null>(null),pub=ref<Row>({site:{name:'序付',english_name:'XUPAY'},products:[],announcements:[]}),loading=ref(true),busy=ref(false),register=ref(false),email=ref(''),password=ref(''),name=ref(''),invite=ref(new URLSearchParams(location.search).get('invite')||''),mobile=ref(false)
const route=ref((location.pathname==='/docs'?'/docs':location.hash.slice(1)||'/home'))
window.addEventListener('hashchange',()=>{route.value=location.pathname==='/docs'?'/docs':location.hash.slice(1)||'/home';mobile.value=false})
const admin=computed(()=>route.value.startsWith('/admin'))
const customerNav=[['/home','工作台',LayoutDashboard],['/subscribe','订阅办理',Sparkles],['/orders','订单中心',ReceiptText],['/wallet','资金账户',Wallet],['/links','结账链接',KeyRound],['/renewal','续费管理',Settings2],['/keys','开发接入',KeyRound],['/invites','伙伴计划',Gift],['/membership','会员中心',ShieldCheck],['/docs','API 文档',BookOpen],['/profile','个人设置',UserRound]] as const
const adminGroups=[{title:'运营洞察',items:[['/admin','运营概览',LayoutDashboard],['/admin/orders','支付全监控',Activity],['/admin/finance','财务报表',ChartNoAxesCombined]]},{title:'客户与经营',items:[['/admin/users','账户管理',Users],['/admin/topups','充值审核',Wallet],['/admin/codes','兑换码',Ticket],['/admin/products','服务与定价',Package],['/admin/membership','会员管理',ShieldCheck]]},{title:'安全与配置',items:[['/admin/risk','风控监控',ShieldCheck],['/admin/resources','代理管理',Server],['/admin/announcements','公告中心',Bell],['/admin/audit','操作审计',ScrollText],['/admin/settings','站点设置',Settings2]]}] as const
const navNames=new Map<string,string>(); for(const n of customerNav)navNames.set(n[0],n[1]);for(const g of adminGroups)for(const n of g.items)navNames.set(n[0],n[1]);
const title=computed(()=>navNames.get(route.value)||'工作台');const goProfile=()=>location.hash='/profile'
async function refresh(){user.value=await api('/me')}
async function loadPublic(){pub.value=await api('/public');document.title=`${pub.value.site.name} · ${pub.value.site.english_name}`}
async function login(){if(busy.value)return;busy.value=true;try{await api(register.value?'/auth/register':'/auth/login','POST',register.value?{email:email.value,password:password.value,name:name.value,invite:invite.value}:{email:email.value,password:password.value});password.value='';await refresh();if(admin.value&&user.value?.role!=='admin')location.hash='/home'}catch(e){notify((e as Error).message)}finally{busy.value=false}}
async function logout(){await action(async()=>{await api('/auth/logout','POST',{});user.value=null;location.hash='/home'})}
let refreshTimer:ReturnType<typeof setInterval>;onUnmounted(()=>clearInterval(refreshTimer));
onMounted(async()=>{try{await loadPublic();try{await refresh()}catch{user.value=null}}catch(e){notify((e as Error).message)}finally{loading.value=false}refreshTimer=setInterval(()=>{if(user.value&&document.visibilityState==='visible')refresh().catch(()=>{})},30000)})
</script>
<template><div class="toast" v-if="toast" role="status"><Check :size="18"/>{{toast}}</div><div v-if="loading" class="boot"><Layers3/><span>正在开启工作台…</span></div>
<ApiDocs v-else-if="route==='/docs'"/><div v-else-if="!user" class="login-page"><div class="login-story"><a href="#/home" class="brand light"><span class="brand-icon"><Layers3 :size="23"/></span><b>{{pub.site.name}}<small>{{pub.site.english_name}}</small></b></a><div class="story-copy"><div class="pill light-pill"><span class="live-dot"/> SUBSCRIPTION, SIMPLIFIED</div><h1>每一份订阅，<br/>都有清晰的<br/><em>下一步。</em></h1><p>从选择服务到查看结果，<br/>一个工作台，让每一笔安排井然有序。</p><div class="story-facts"><span><ShieldCheck :size="18"/>安全的账户空间</span><span><ReceiptText :size="18"/>可追溯的资金记录</span></div></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="story-bottom">DESIGNED FOR CLARITY <span>01 / 简单 · 可靠 · 有序</span></div></div><div class="login-form-side"><div class="login-top">订阅服务工作台 <span>中文 / ZH</span></div><form class="login-form" @submit.prevent="login"><div class="eyebrow">WELCOME TO {{pub.site.english_name}}</div><h2>{{register?'建立你的专属空间':'欢迎回来'}}</h2><p class="muted">{{register?'用一个账户，管理每一次订阅。':'登录后继续管理你的服务与资金。'}}</p><div class="segmented"><button type="button" :class="{active:!register}" @click="register=false">登录账户</button><button type="button" :class="{active:register}" :disabled="!pub.site.registration_open" @click="register=true">创建账户</button></div><label v-if="register">你的称呼<input v-model="name" required maxlength="80" placeholder="怎么称呼你" autocomplete="nickname"/></label><label>邮箱地址<input v-model="email" type="email" required placeholder="name@example.com" autocomplete="email"/></label><label>账户密码<input v-model="password" type="password" required :minlength="register?10:1" maxlength="72" placeholder="输入你的密码" :autocomplete="register?'new-password':'current-password'"/></label><label v-if="register">邀请标识（选填）<input v-model="invite" placeholder="来自伙伴的邀请标识"/></label><button class="btn primary full" :disabled="busy">{{busy?'请稍候…':register?'创建账户':'进入工作台'}}<ArrowRight :size="18"/></button><div class="login-hint"><ShieldCheck :size="15"/>仅在你自己的账户空间查看业务资料</div></form><div v-if="pub.announcements.length" class="login-announcements"><Bell :size="16"/><div class="marquee"><div><span v-for="a in pub.announcements" :key="a.id">{{a.title}} · {{a.body}}</span></div></div></div><footer>© {{new Date().getFullYear()}} {{pub.site.english_name}} · 让服务更清晰</footer></div></div>
<div v-else :class="['shell',admin?'admin-shell':'customer-shell']"><header class="topbar"><a href="#/home" class="brand"><span class="brand-icon"><Layers3 :size="22"/></span><b>{{pub.site.name}}<small>{{pub.site.english_name}}</small></b></a><span class="console-label">{{admin?'运营控制台':'订阅工作台'}} <span class="pill">{{admin?'ADMIN':'WORKSPACE'}}</span></span><div class="top-actions"><a v-if="user.membership" href="#/membership" class="membership-badge" :title="user.membership.current.name">{{user.membership.current.code}} · {{user.membership.current.name}}</a><a v-if="user.role==='admin'" :href="admin?'#/home':'#/admin'" target="_blank" rel="noopener noreferrer" class="mode-switch">{{admin?'客户工作台':'运营控制台'}}<ArrowUpRight :size="14"/></a><a class="wallet-chip" href="#/wallet"><Wallet :size="15"/><b>{{cash(user.balance)}}</b><small>R</small></a><button class="avatar" @click="goProfile" :aria-label="user.name">{{user.name.slice(0,1)}}</button><button class="icon-btn mobile-only" @click="mobile=!mobile" aria-label="展开菜单"><Menu :size="21"/></button><button class="icon-btn desktop-only" @click="logout" title="退出登录" aria-label="退出登录"><LogOut :size="18"/></button></div></header>
<aside class="sidebar" :class="{mobileOpen:mobile}"><button class="icon-btn mobile-only close-nav" @click="mobile=false" aria-label="收起菜单"><X/></button><template v-if="admin"><div class="side-greeting"><span class="eyebrow">OPERATIONS</span><h3>掌握每一处变化。</h3></div><section v-for="g in adminGroups" :key="g.title"><p>{{g.title}}</p><a v-for="n in g.items" :key="n[0]" :href="'#'+n[0]" :class="{active:route===n[0]}"><component :is="n[2]" :size="18"/>{{n[1]}}<span v-if="route===n[0]" class="nav-dot"></span></a></section><div class="side-foot"><span class="live-dot"/><span>本地独立运行<small>CHECKOUT · 结账准备</small></span></div></template><template v-else><div class="side-greeting"><span class="eyebrow">MY WORKSPACE</span><h3>让每一笔，井然有序。</h3></div><section><p>订阅与资金</p><a v-for="n in customerNav.slice(0,4)" :key="n[0]" :href="n[0]==='/docs'?'/docs':'#'+n[0]" :target="n[0]==='/docs'?'_blank':undefined" :rel="n[0]==='/docs'?'noopener noreferrer':undefined" :class="{active:route===n[0]}"><component :is="n[2]" :size="18"/>{{n[1]}}<span v-if="route===n[0]" class="nav-dot"></span></a></section><section><p>工具与账户</p><a v-for="n in customerNav.slice(4)" :key="n[0]" :href="n[0]==='/docs'?'/docs':'#'+n[0]" :target="n[0]==='/docs'?'_blank':undefined" :rel="n[0]==='/docs'?'noopener noreferrer':undefined" :class="{active:route===n[0]}"><component :is="n[2]" :size="18"/>{{n[1]}}<span v-if="route===n[0]" class="nav-dot"></span></a></section><div class="side-foot"><ShieldCheck :size="17"/><span>你的专属服务空间<small>CLARITY IN EVERY STEP</small></span></div><button class="btn secondary mobile-only" @click="logout" style="margin-top:20px;width:100%">退出登录</button></template></aside>
<main :class="['main',admin?'admin-main':'customer-main']"><div class="breadcrumb"><span>{{admin?'运营中心':'我的空间'}}</span><span>/</span><b>{{title}}</b><span class="breadcrumb-end">{{new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}}</span></div><Admin v-if="admin&&user.role==='admin'" :key="route" :route="route" :user="user" @refresh="refresh" @public-refresh="loadPublic"/><div v-else-if="admin" class="empty"><ShieldCheck/><h2>此页面仅对管理员开放</h2><a href="#/home" class="btn primary">返回工作台</a></div><Customer v-else :key="route" :route="route" :user="user" :pub="pub" @refresh="refresh" @logout="logout"/><footer class="workspace-footer"><span>{{pub.site.english_name}} / 清晰记录每一步</span><div><a href="#/keys">开发接入</a><a href="#/profile">账户设置</a><a v-if="pub.site.support_url" :href="pub.site.support_url" target="_blank" rel="noopener noreferrer">联系支持</a></div></footer></main></div></template>
